const IFC_FLOW_PROOF_SCHEMA_VERSION: &str = "frankenengine.ir2_flow_proof_witness.v1";
const LEXICAL_BINDING_SENTINEL_PREFIX: &str = "\0lexical\0";
const CAPTURE_ORIGIN_SENTINEL_PREFIX: &str = "\0capture-origin\0";
const CAPTURE_CELL_NAME_PREFIX: &str = "\0capture-cell\0";
const GLOBAL_OBJECT_CAPTURE_PREFIX: &str = "\0global-object-binding\0";
const STRICT_ASSIGNMENT_CONTEXT_SENTINEL: &str = "\0strict-assignment-context";
const CLASS_EXPRESSION_SELF_CAPTURE_PREFIX: &str = "\0class-expression-self\0";
const CHILD_CAPTURE_BINDING_SENTINEL_PREFIX: &str = "\0child-capture\0";
const RUNTIME_LEXICAL_BINDING_NAME_PREFIX: &str = "\0runtime-lexical\0";
const TYPEOF_DYNAMIC_NAME_SENTINEL_PREFIX: &str = "\0typeof-dynamic\0";
const AUTHENTICATED_COMMONJS_RUNTIME_BINDINGS: [&str; 5] =
    ["require", "exports", "module", "__filename", "__dirname"];
/// Records the binding id of the authenticated CommonJS `require` so builtin
/// recognizers can tell it from a source declaration. It carries the lexical
/// prefix so fresh function bodies inherit it with the other lexical markers;
/// the NUL-led name can never be a source identifier.
const CANONICAL_COMMONJS_REQUIRE_SENTINEL: &str = "\0lexical\0\0canonical-commonjs-require";
/// Inherited with lexical markers so deferred functions retain the installed
/// resolver boundary instead of rewriting their loads into builtin facades.
const PRESERVE_RUNTIME_MODULE_LOADS_SENTINEL: &str = "\0lexical\0\0preserve-runtime-module-loads";

/// Maximum number of IR1 ops to preallocate based on AST size (prevents pathological growth).
const MAX_PREALLOC_OPS: usize = 1_000_000; // 1M ops max

/// Maximum number of bindings to preallocate based on AST size (prevents pathological growth).
const MAX_PREALLOC_BINDINGS: usize = 250_000; // 250K bindings max

fn lexical_binding_sentinel(name: &str) -> String {
    format!("{LEXICAL_BINDING_SENTINEL_PREFIX}{name}")
}

fn typeof_dynamic_name_sentinel(name: &str) -> String {
    format!("{TYPEOF_DYNAMIC_NAME_SENTINEL_PREFIX}{name}")
}

fn capture_origin_sentinel(name: &str) -> String {
    format!("{CAPTURE_ORIGIN_SENTINEL_PREFIX}{name}")
}

/// The entries of `lookup` whose keys start with `prefix`. Keys order by
/// their bytes, so they are one contiguous range: reading it costs its own
/// length, not the whole lookup's, which every function body would otherwise
/// pay once per sentinel family (bd-9vouw.223).
fn prefixed_entries<'a>(
    lookup: &'a BTreeMap<String, BindingId>,
    prefix: &'a str,
) -> impl Iterator<Item = (&'a String, &'a BindingId)> + 'a {
    lookup
        .range::<str, _>((Bound::Included(prefix), Bound::Unbounded))
        .take_while(move |(key, _)| key.starts_with(prefix))
}

/// The entries of `lookup` whose keys do not start with NUL (the sentinel
/// families), in key order.
fn non_sentinel_entries(
    lookup: &BTreeMap<String, BindingId>,
) -> impl Iterator<Item = (&String, &BindingId)> {
    lookup
        .range::<str, _>((Bound::Unbounded, Bound::Excluded("\0")))
        .chain(lookup.range::<str, _>((Bound::Included("\u{1}"), Bound::Unbounded)))
}

/// Copy every outer key under one of `prefixes` into a function body's
/// lookup (with id 0, as the module-alias provenance sentinels carry).
fn seed_prefixed_sentinels(
    body_lookup: &mut BTreeMap<String, BindingId>,
    outer_lookup: &BTreeMap<String, BindingId>,
    prefixes: &[&str],
) {
    for prefix in prefixes {
        for (key, _) in prefixed_entries(outer_lookup, prefix) {
            body_lookup.insert(key.clone(), 0);
        }
    }
}

/// The binding id of a CommonJS wrapper binding (`module`, `exports`,
/// `require`, `__filename`, `__dirname`) declared at a CommonJS unit's root.
/// It carries the lexical prefix, so nested function bodies inherit it; the
/// NUL-led remainder can never be a source identifier.
fn commonjs_wrapper_sentinel(name: &str) -> String {
    format!("{LEXICAL_BINDING_SENTINEL_PREFIX}\0commonjs-wrapper\0{name}")
}

/// Whether `name`, as seen from a function body whose enclosing lookup is
/// `outer_lookup`, is the CommonJS wrapper binding itself rather than a
/// source binding of the same name (bd-rff5g). The loader writes the wrapper
/// bindings into the module's runtime scope frame, not into a capture cell,
/// so a nested function reads them by name through its captured scope chain.
fn is_commonjs_wrapper_reference(outer_lookup: &BTreeMap<String, BindingId>, name: &str) -> bool {
    outer_lookup
        .get(&commonjs_wrapper_sentinel(name))
        .is_some_and(|wrapper| outer_lookup.get(&capture_origin_sentinel(name)) == Some(wrapper))
}

/// Marks the body-local bridge `materialize_source_binding_id` made for a
/// CommonJS wrapper binding (bd-9vouw.211). A nested body that assigns the
/// wrapper (`module.exports = exports = factory()`) stores through the
/// bridge, and the marker tells `rewrite_unresolved_function_body_loads`
/// that the store targets the module's binding rather than a declaration of
/// the body. Not lexical-prefixed: nested bodies do not inherit it and a
/// block's marker restore keeps it.
fn commonjs_wrapper_bridge_marker(binding_id: BindingId) -> String {
    format!("\0commonjs-wrapper-bridge\0{binding_id}")
}

fn capture_cell_name(name: &str, origin_id: BindingId) -> String {
    format!("{CAPTURE_CELL_NAME_PREFIX}{origin_id}\0{name}")
}

fn parse_capture_cell_name(name: &str) -> Option<(BindingId, &str)> {
    let encoded = name.strip_prefix(CAPTURE_CELL_NAME_PREFIX)?;
    let (origin_id, source_name) = encoded.split_once('\0')?;
    Some((origin_id.parse().ok()?, source_name))
}

fn script_global_binding_sentinel(name: &str) -> String {
    format!("{LEXICAL_BINDING_SENTINEL_PREFIX}\0script-global-binding\0{name}")
}

fn is_script_global_binding(binding_lookup: &BTreeMap<String, BindingId>, name: &str) -> bool {
    binding_lookup
        .get(&script_global_binding_sentinel(name))
        .is_some_and(|origin| binding_lookup.get(&capture_origin_sentinel(name)) == Some(origin))
}

fn known_assignment_strictness(strictness: AssignmentStrictness) -> Option<bool> {
    match strictness {
        AssignmentStrictness::Strict => Some(true),
        AssignmentStrictness::Sloppy => Some(false),
        AssignmentStrictness::Unknown => None,
    }
}

fn global_object_capture_name(name: &str) -> Option<&str> {
    name.strip_prefix(GLOBAL_OBJECT_CAPTURE_PREFIX)
}

fn class_expression_self_capture_name(name: &str, origin_id: BindingId) -> String {
    format!("{CLASS_EXPRESSION_SELF_CAPTURE_PREFIX}{origin_id}\0{name}")
}

fn parse_class_expression_self_capture_name(name: &str) -> Option<(BindingId, &str)> {
    let encoded = name.strip_prefix(CLASS_EXPRESSION_SELF_CAPTURE_PREFIX)?;
    let (origin_id, source_name) = encoded.split_once('\0')?;
    Some((origin_id.parse().ok()?, source_name))
}

fn child_capture_binding_sentinel(binding_id: BindingId, runtime_name: &str) -> String {
    format!("{CHILD_CAPTURE_BINDING_SENTINEL_PREFIX}{binding_id}\0{runtime_name}")
}

fn parse_child_capture_binding_sentinel(name: &str) -> Option<(BindingId, &str)> {
    let encoded = name.strip_prefix(CHILD_CAPTURE_BINDING_SENTINEL_PREFIX)?;
    let (binding_id, runtime_name) = encoded.split_once('\0')?;
    Some((binding_id.parse().ok()?, runtime_name))
}

fn runtime_lexical_binding_name(binding_id: BindingId, source_name: &str) -> String {
    format!("{RUNTIME_LEXICAL_BINDING_NAME_PREFIX}{binding_id}\0{source_name}")
}

fn runtime_scope_binding_name(
    binding_id: BindingId,
    runtime_names: &BTreeMap<BindingId, String>,
) -> String {
    runtime_names
        .get(&binding_id)
        .cloned()
        .unwrap_or_else(|| format!("__binding_{binding_id}"))
}

fn has_source_lexical_binding(binding_lookup: &BTreeMap<String, BindingId>, name: &str) -> bool {
    binding_lookup.contains_key(&lexical_binding_sentinel(name))
}

/// A script's global declaration of an immutable value property cannot
/// shadow that property. The origin distinguishes it from a block-local
/// binding of the same spelling; function-local declarations clear the
/// inherited marker because each function restarts its binding-id space.
fn script_global_value_sentinel(name: &str) -> String {
    format!("{LEXICAL_BINDING_SENTINEL_PREFIX}\0script-global-value\0{name}")
}

fn global_value_literal(name: &str) -> Option<Ir1Literal> {
    match name {
        "undefined" => Some(Ir1Literal::Undefined),
        "NaN" => Some(Ir1Literal::Float(f64::NAN.to_bits())),
        "Infinity" => Some(Ir1Literal::Float(f64::INFINITY.to_bits())),
        _ => None,
    }
}

/// Constant-fold only an immutable global reference, after name resolution.
/// Synthetic UndefinedLiteral/FloatLiteral AST values remain literals even
/// when source code declares a local with the corresponding global name.
fn unshadowed_global_value(
    binding_lookup: &BTreeMap<String, BindingId>,
    name: &str,
) -> Option<Ir1Literal> {
    let value = global_value_literal(name)?;
    let is_global = !has_source_lexical_binding(binding_lookup, name)
        || binding_lookup
            .get(&script_global_value_sentinel(name))
            .is_some_and(|origin| {
                binding_lookup.get(&capture_origin_sentinel(name)) == Some(origin)
            });
    is_global.then_some(value)
}

/// Materialize the body-local bridge used to address a source lexical binding
/// inherited from an enclosing lowering unit.
///
/// Fresh function bodies copy lexical-visibility sentinels, but intentionally
/// do not copy ordinary name entries. The first actual read or write allocates
/// this deterministic bridge; `collect_free_vars` later connects it to the
/// enclosing cell. Truly unresolved names never reach this helper.
fn materialize_source_binding_id(
    bindings: &mut Vec<ResolvedBinding>,
    binding_lookup: &mut BTreeMap<String, BindingId>,
    binding_index: &mut BindingId,
    scope_id: ScopeId,
    name: &str,
) -> Result<BindingId, LoweringPipelineError> {
    if let Some(&binding_id) = binding_lookup.get(name) {
        return Ok(binding_id);
    }
    if !has_source_lexical_binding(binding_lookup, name) {
        return Err(LoweringPipelineError::InvariantViolation {
            detail: "cannot materialize a non-lexical source binding",
        });
    }

    let binding_id = *binding_index;
    *binding_index = binding_index.saturating_add(1);
    bindings.push(ResolvedBinding {
        name: name.to_string(),
        binding_id,
        scope: scope_id,
        kind: BindingKind::Let,
    });
    binding_lookup.insert(name.to_string(), binding_id);
    if is_commonjs_wrapper_reference(binding_lookup, name) {
        binding_lookup.insert(commonjs_wrapper_bridge_marker(binding_id), binding_id);
    }
    Ok(binding_id)
}

fn assignment_strictness_is_strict(
    assignment_strictness: AssignmentStrictness,
) -> Result<bool, LoweringPipelineError> {
    match assignment_strictness {
        AssignmentStrictness::Sloppy => Ok(false),
        AssignmentStrictness::Strict => Ok(true),
        AssignmentStrictness::Unknown => Err(LoweringPipelineError::InvariantViolation {
            detail: "unresolved assignment target has unknown strictness provenance; reparse the source with the current AST schema",
        }),
    }
}

/// bd-9vouw.146: whether a member write throws when [[Set]] rejects it.
/// Only a write known to be sloppy is lenient; a legacy serialized AST
/// (`Unknown`) keeps the throwing write it always had.
fn member_assignment_is_strict(assignment_strictness: AssignmentStrictness) -> bool {
    !matches!(assignment_strictness, AssignmentStrictness::Sloppy)
}

fn is_lexically_shadowed(binding_lookup: &BTreeMap<String, BindingId>, name: &str) -> bool {
    binding_lookup.contains_key(name)
        || has_source_lexical_binding(binding_lookup, name)
        || binding_lookup.contains_key(&typeof_dynamic_name_sentinel(name))
}

/// Whether a `require` callee may be read as Node's own `require` by the
/// builtin-module recognizers (`require('fs')`, `require('node:path')`, ...):
/// either the ambient identifier, or the authenticated CommonJS wrapper
/// binding when that injected binding is the one visible here (bd-rff5g).
/// Any source declaration of `require` (parameter, `let`, `var`, function,
/// block scope) carries a different binding id and keeps the recognizers off.
/// Only the recognizers use this; a plain `require(...)` call on the wrapper
/// binding still lowers to a call of the runtime loader.
fn is_builtin_require_callee(binding_lookup: &BTreeMap<String, BindingId>, name: &str) -> bool {
    if name != "require" || binding_lookup.contains_key(PRESERVE_RUNTIME_MODULE_LOADS_SENTINEL) {
        return false;
    }
    if !is_lexically_shadowed(binding_lookup, name) {
        return true;
    }
    let Some(&injected) = binding_lookup.get(CANONICAL_COMMONJS_REQUIRE_SENTINEL) else {
        return false;
    };
    match binding_lookup.get(name) {
        Some(&visible) => visible == injected,
        None => binding_lookup.get(&capture_origin_sentinel(name)) == Some(&injected),
    }
}

/// Whether `require` here is the authenticated CommonJS wrapper binding
/// (bd-rff5g), whose call reaches the runtime loader, rather than the ambient
/// name a script would refuse.
fn require_is_commonjs_wrapper(binding_lookup: &BTreeMap<String, BindingId>) -> bool {
    let Some(&injected) = binding_lookup.get(CANONICAL_COMMONJS_REQUIRE_SENTINEL) else {
        return false;
    };
    match binding_lookup.get("require") {
        Some(&visible) => visible == injected,
        None => binding_lookup.get(&capture_origin_sentinel("require")) == Some(&injected),
    }
}

fn is_internal_lowering_binding(name: &str) -> bool {
    name.starts_with('<') || name.starts_with("@@franken_internal_") || name.starts_with('\0')
}

/// Ambient-authority grant applied to a whole lowering unit at its root scope.
///
/// The lowering-time ambient-authority gate is deny-by-default: a raw ambient
/// identifier (`eval`, `require`, `fetch`, `process`, …) is rejected unless the
/// unit's grant permits the [`EffectKind`] that access requires. Untrusted
/// extension / red-team lowering runs under [`Self::DenyAll`] (the fail-closed
/// default), so no ambient authority is reachable and every red-team scenario
/// is rejected at lowering. A *trusted* top-level eval context
/// (`QuickJsInspiredNativeEngine::eval`) runs under [`Self::TrustedProcessShape`],
/// which grants only the benign [`EffectKind::ProcessShapeRead`] effect. Explicitly
/// admitted executions preserve this grant when lowering their dependencies.
/// The grant is consumed only by statically allowlisted `process.<shape>` reads;
/// bare, aliased, and computed `process` access stays denied, as do env *values*
/// (`process.env.X` → [`EffectKind::EnvRead`]), `eval`, fs, network, and spawn.
///
/// This is the seam bd-xewby threads so BOTH the minimal-`process`-global
/// feature and every red-team rejection hold at once: trusted eval sees the
/// process shape; untrusted extension lowering sees nothing. It is
/// unit-uniform (applied at the root scope); per-scope grants are a future
/// extension of the same seam.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Default, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum AmbientAuthorityGrant {
    /// No ambient authority reachable through raw ambient identifiers. The
    /// fail-closed default for untrusted extension / red-team lowering.
    #[default]
    DenyAll,
    /// Statically allowlisted `process.<shape>` reads are permitted; possession
    /// of the bare object, aliases, computed access, env values, `eval`, fs,
    /// network, and spawn remain denied. For explicitly admitted executions
    /// and the dependencies loaded into the same execution.
    TrustedProcessShape,
}

impl AmbientAuthorityGrant {
    /// The ambient-authority [`EffectSet`] this grant confers on a unit's root
    /// scope. `DenyAll` confers the empty (deny-by-default) set.
    fn root_effect_set(self) -> EffectSet {
        match self {
            Self::DenyAll => EffectSet::new(),
            Self::TrustedProcessShape => EffectSet::from_iter_of([EffectKind::ProcessShapeRead]),
        }
    }
}

#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
pub struct LoweringContext {
    pub trace_id: String,
    pub decision_id: String,
    pub policy_id: String,
    /// Ambient-authority grant for this lowering unit. Defaults to
    /// [`AmbientAuthorityGrant::DenyAll`]; only a trusted top-level eval sets
    /// [`AmbientAuthorityGrant::TrustedProcessShape`]. `#[serde(default)]` keeps
    /// older serialized contexts (no field) deserializing as deny-all.
    #[serde(default)]
    pub ambient_authority_grant: AmbientAuthorityGrant,
    /// Authenticated provenance floor for guest-visible filesystem effect
    /// errors. The default remains fail-high for lowering entrypoints that do
    /// not bind every possible live or replay outcome source.
    #[serde(default)]
    pub host_io_exception_provenance: HostIoExceptionProvenance,
    /// Whether the caller has authenticated a CommonJS loader environment
    /// that will inject the canonical wrapper bindings before execution.
    /// Source labels alone never enable this; the resolved CJS loader must opt
    /// in explicitly so arbitrary scripts retain deny-all ambient authority.
    #[serde(default)]
    pub authenticated_commonjs_runtime_bindings: bool,
    /// Keep every source import and require on the runtime module boundary.
    /// An installed resolver must authorize these requests before a native
    /// builtin provider or cached module can be used. This does not grant
    /// CommonJS bindings, module authority, or any builtin capability.
    #[serde(default)]
    pub preserve_runtime_module_loads: bool,
}

impl LoweringContext {
    pub fn new(
        trace_id: impl Into<String>,
        decision_id: impl Into<String>,
        policy_id: impl Into<String>,
    ) -> Self {
        Self {
            trace_id: trace_id.into(),
            decision_id: decision_id.into(),
            policy_id: policy_id.into(),
            ambient_authority_grant: AmbientAuthorityGrant::DenyAll,
            host_io_exception_provenance: HostIoExceptionProvenance::Unknown,
            authenticated_commonjs_runtime_bindings: false,
            preserve_runtime_module_loads: false,
        }
    }

    /// Builder: set the ambient-authority grant for this lowering unit. Used by
    /// trusted evaluation and explicitly admitted executions to grant the
    /// benign process-shape profile, including their loaded dependencies.
    /// Generated code and other callers retain the deny-all default.
    pub fn with_ambient_authority_grant(mut self, grant: AmbientAuthorityGrant) -> Self {
        self.ambient_authority_grant = grant;
        self
    }

    /// Bind lowering to the effective host-I/O source's authenticated
    /// filesystem exception provenance contract.
    pub fn with_host_io_exception_provenance(
        mut self,
        provenance: HostIoExceptionProvenance,
    ) -> Self {
        self.host_io_exception_provenance = provenance;
        self
    }

    /// Bind lowering to the authenticated CommonJS wrapper environment that
    /// the module loader constructs before executing the resulting IR.
    pub fn with_authenticated_commonjs_runtime_bindings(mut self) -> Self {
        self.authenticated_commonjs_runtime_bindings = true;
        self
    }

    /// Preserve source load sites for the runtime resolver. Builtin rewrites
    /// cannot replace these requests with lowering-time facade authority.
    pub fn with_preserved_runtime_module_loads(mut self) -> Self {
        self.preserve_runtime_module_loads = true;
        self
    }
}

