                            let obj = pop_lowering_value(&mut fn_value_stack)?;
                            let kr = alloc_register(&mut fn_reg);
                            let pool_index = push_constant_optimized(&mut constant_pool, k.clone());
                            ir3.instructions.push(Ir3Instruction::LoadStr {
                                dst: kr,
                                pool_index,
                            });
